import{_ as d,l as n,o as e,c as l,v as t,p as s,x as r,d as E,i,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Nested CPCV","description":"","frontmatter":{"title":"Nested CPCV","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/nested-cpcv.md","filePath":"quant/nested-cpcv.md","lastUpdated":1789023840000}'),p={name:"quant/nested-cpcv.md"};function B(C,a,A,m,P,h){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="nested-cpcv" tabindex="-1">Nested CPCV <a class="header-anchor" href="#nested-cpcv" aria-label="Permalink to &quot;Nested CPCV&quot;">​</a></h1><div class="epigraph"><p>组合划分生成许多条清洗后的样本外路径；若路径上的分数还被用来选窗口、选特征、选成本假设，路径就不再是评估。必须把网格关在每条外层训练块的内层，把外层测试块留给从未参与选择的分数。</p><footer>—— 嵌套评估见 Varma–Simon、Cawley–Talbot；组合清洗划分见 López de Prado, AFML, Chapter 12；PBO 见 Bailey et al., 2017</footer></div><p><a href="/quant/nested-cv">嵌套交叉验证</a> 写内层选、外层评这一纪律，默认外层是滚动或时间块。<a href="/quant/cpcv">组合过拟合 CPCV</a> 与 <a href="/quant/cpcv-lopez">Combinatorial Purged CV</a> 写如何用 \\(\\binom{N}{k}\\) 种划分生成许多条 purge 之后的路径，以及如何用路径去估 PBO 或单个估计器的划分敏感性。Nested CPCV 把两件事接起来：<strong>外层用组合清洗划分做评估，内层只在外层训练块上再做一次组合（或滚动）搜索。</strong> 它针对的是业界最常见的操作：已经上了 CPCV，却用路径中位数去挑超参数，等于把 \\(\\varphi\\) 条路径又变成一次选择。Bailey 的 PBO 假设候选列表已冻结；网格尚未冻结时，内层就是在生成候选，必须嵌套。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设超参数 \\(\\lambda\\) 含窗口、正则、特征子集、是否加某过滤器、成本假设。非嵌套 CPCV 的做法是：对每个 \\(\\lambda\\) 跑全套组合路径，得到路径中位夏普或 PBO，再挑最好的 \\(\\lambda^\\star\\)，把该 \\(\\lambda^\\star\\) 的路径分布写进研报。错误与非嵌套 \\(K\\) 折相同：用于选择的分数就是用于报告的分数。组合次数越多，越容易挑到「在这些切法上碰巧稳」的 \\(\\lambda\\)，PBO 看起来很好，只是对划分方案过拟合。</p><p>Walk-forward 嵌套给出一条可部署曲线，但路径太少，看不清选择偏差。纯 CPCV 路径多，但不嵌套则评估有偏。问题是给出一个协议：外层组合的测试组从不进入网格；内层可以用 CPCV、滚动或普通清洗 \\(K\\) 折，只在外层训练组上运行；最终报告的是外层测试分数的分布，以及——若候选已在内层生成——外层上的 PBO。</p><h3 id="两层组合的信息集" tabindex="-1">两层组合的信息集 <a class="header-anchor" href="#两层组合的信息集" aria-label="Permalink to &quot;两层组合的信息集&quot;">​</a></h3><p>外层：时间上 \\(N\\) 个连续组，每次取 \\(k\\) 组当测试，其余当训练，purge 与 embargo 按 <a href="/quant/purge-embargo">清洗与禁运</a>。对每一个外层组合 \\(c\\)，记训练索引 \\(T_c\\)、测试索引 \\(E_c\\)。内层：仅在 \\(T_c\\) 上再切组或再滚动，搜索 \\(\\lambda\\)，得到 \\(\\lambda^\\star_c\\)。然后只在 \\(E_c\\) 上评估一次 \\(\\lambda^\\star_c\\)（特征管道也只在 \\(T_c\\) 上 <code>fit</code>）。\\(\\lambda^\\star_c\\) 可以随 \\(c\\) 变，这是非平稳下应该发生的事。把各 \\(c\\) 的 \\(\\lambda^\\star\\) 平均成一个部署参数，只是为了上线；评估数字仍用外层。</p><p><span class="marginnote">sklearn 式 <code>GridSearchCV</code> 的 <code>best_score_</code> 换成本上「CPCV 路径中位最好的那组窗口」，错误同构。早停、特征筛列、拥挤过滤器阈值，全部是 \\(\\lambda\\) 的坐标，全部只能待在内层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>内层选什么评估器。</strong> 内层目的是选择，不是再估一遍 PBO。内层路径可以较少：例如在 \\(T_c\\) 上做 purged \\(K\\) 折或较小的 \\((N_{\\mathrm{in}},k_{\\mathrm{in}})\\)，按扣费后效用的中位或预先声明的分位选 \\(\\lambda\\)。不要在内层用路径最大值选——那是把选择偏差再放大一级。订单级回测放在外层最终 \\(\\lambda^\\star_c\\) 上，内层用同一套标签与成本模型的向量化评分。</p><p><strong>外层报什么。</strong> 每个 \\(c\\) 一个外层分数，对齐成 \\(\\varphi=\\binom{N-1}{k-1}\\) 条完整路径（计数见 CPCV 专文），报告中位数、分位、最差路径。若内层输出的是「冠军配置」而候选集合在各 \\(c\\) 之间可比，还可在外层算 PBO：训练块上内层选出的冠军，在测试块上相对一个<strong>预先冻结的参照集合</strong>的排名。参照集合不能是「内层刚淘汰的那些」，否则相对排名没有定义。更干净的做法是：PBO 只在候选已闭合的那一层算；嵌套 CPCV 先把网格收成一个估计器（选择程序），再对该程序做路径分布。</p><p><strong>计算。</strong> 外层 \\(\\binom{N}{k}\\) 乘内层组合数乘网格。必须先靠经济约束削薄网格（换手上限、可交易宇宙、禁止未来函数），嵌套不是对任意宽搜索的许可证。配置向量化；内层禁止逐笔。评分函数若含全样本标准化，嵌套只是把泄漏嵌套地复制，见 <a href="/quant/cv-leakage-finance">金融交叉验证泄漏</a>。</p><h3 id="与-pbo、dsr、因果滚动的串联" tabindex="-1">与 PBO、DSR、因果滚动的串联 <a class="header-anchor" href="#与-pbo、dsr、因果滚动的串联" aria-label="Permalink to &quot;与 PBO、DSR、因果滚动的串联&quot;">​</a></h3><p>一个完整协议：（1）用 Nested CPCV 得到选择程序的外层路径分布；（2）若候选列表已闭合，用 CSCV/CPCV 报 PBO；（3）用 DSR 把尝试次数与非正态写进最终夏普的检验；（4）另跑一条预先声明的 walk-forward，作为可审计的因果曲线。四者不可互相替代。只用嵌套 CPCV 的路径中位当「样本外夏普」，仍没有时间顺序上的部署叙事；只用 PBO，网格若未进内层，数字假低。</p><p>特征选择、标准化、PCA、行业收益，必须 <code>fit</code> 在当前内层训练折。拥挤指标的阈值、CPPI 乘数、HAR 的对数变换，同样是 \\(\\lambda\\)。任何「我们试了几种，取了验证最好的」都要么嵌套，要么把尝试计入 DSR 的 \\(N\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>非嵌套的乐观来自对验证分数取最大值。CPCV 把验证换成许多条路径，最大值变成「路径中位的最大值」或「PBO 的最小值」，偏差形式更隐蔽，机制不变：噪声在选择中被挑中，测试若共享同一噪声（未 purge）或共享同一选择所用的路径，条件期望偏高。嵌套把最大值锁在 \\(T_c\\) 内部，\\(E_c\\) 看到的是选择程序在新块上的实现。</p><p>组合划分相对滚动的机制优势是：每段历史都有机会当外层测试，选择偏差不被单一牛市尾巴掩盖。代价是交错块不模拟部署顺序，外层路径分布估的是划分敏感性与选择程序风险，不是冲击与容量。容量仍用因果滚动加<a href="/quant/crowding-capacity-metric">拥挤与容量指标</a>。</p><p><span class="marginnote">外层分数无偏，是相对「同一数据生成过程上的选择过程」而言。非平稳下，无偏不等于可外推到下一体制。嵌套之后仍应保留从未碰过的持有期，或承认没有这样的样本。</span></p><h3 id="何时不必上双层组合" tabindex="-1">何时不必上双层组合 <a class="header-anchor" href="#何时不必上双层组合" aria-label="Permalink to &quot;何时不必上双层组合&quot;">​</a></h3><p>\\(\\lambda\\) 在样本开始前冻结（预注册、沿用旧产品参数），没有选择，单层 CPCV 或单层滚动即可。网格极粗且所有格子外层几乎一样，嵌套与否差几个基点——仍须报告「未选择」。危险的是中等宽度网格：看起来克制，恰好够拟合一段划分噪声。计算预算不够时，正确的降级是削网格并预注册，而不是回到非嵌套的路径中位选美。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Nested CPCV 不修复前视特征、不修复未来成交量的 VWAP、不修复全样本行业分类修订。外层若仍打乱时间，泄漏优先于嵌套。也不要把外层 \\(\\varphi\\) 条路径的最大值写成样本外夏普。部署需要单一 \\(\\lambda\\) 时，在全部训练历史（不含最终持有期）上重跑一次内层，评估仍只用外层历史路径。</p><p>内层目标必须与外层评估对齐：内层毛 \\(R^2\\)、外层扣费夏普，会选出高换手。两边都应是扣费后、容量约束后的同一效用。\\((N,k)\\) 与内层方案预先冻结并做敏感性，禁止挑让外层中位最高的那组划分参数——那是第三层过拟合。</p><p><span class="marginnote">看到外层 PBO 偏高就删候选再跑，协议作废。诚实做法是扩大报告：给出搜索日志上的嵌套结果，而不是清洗后集合上的结果。Bailey 等人警告过把评估器当优化目标。</span></p>',26)),(e(),s(c,null,{default:r(()=>[i(o,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TD%0A%20%20DATA%5B%22%E6%97%B6%E9%97%B4%E6%9C%89%E5%BA%8F%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20OUT%5B%22%E5%A4%96%E5%B1%82%20CPCV%3A%20%E8%AE%AD%E7%BB%83%E7%BB%84%20%2F%20%E6%B5%8B%E8%AF%95%E7%BB%84%20%2B%20purge%22%5D%0A%20%20OUT%20--%3E%20IN%5B%22%E4%BB%85%E5%9C%A8%E5%A4%96%E5%B1%82%E8%AE%AD%E7%BB%83%E7%BB%84%E4%B8%8A%3A%20%E5%86%85%E5%B1%82%20CV%20%E6%88%96%20CPCV%22%5D%0A%20%20IN%20--%3E%20GRID%5B%22%E6%90%9C%E7%B4%A2%20%CE%BB%E3%80%81%E7%89%B9%E5%BE%81%E3%80%81%E7%AA%97%E5%8F%A3%E3%80%81%E8%BF%87%E6%BB%A4%E5%99%A8%22%5D%0A%20%20GRID%20--%3E%20LAM%5B%22%CE%BB*_c%22%5D%0A%20%20LAM%20--%3E%20EVAL%5B%22%E5%8F%AA%E5%9C%A8%E5%A4%96%E5%B1%82%E6%B5%8B%E8%AF%95%E7%BB%84%E8%AF%84%E4%BC%B0%E4%B8%80%E6%AC%A1%22%5D%0A%20%20EVAL%20--%3E%20DIST%5B%22%E5%A4%96%E5%B1%82%E8%B7%AF%E5%BE%84%E5%88%86%E5%B8%83%20%2F%20%E5%8F%AF%E9%80%89%20PBO%22%5D%0A%20%20DIST%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%E5%88%86%E5%B8%83%2C%20%E7%A6%81%E6%AD%A2%E5%86%8D%E9%80%89%E6%9C%80%E5%A4%A7%E5%80%BC%22%5D%0A%20%20WF%5B%22%E9%A2%84%E5%85%88%E5%A3%B0%E6%98%8E%E7%9A%84%E5%9B%A0%E6%9E%9C%E6%BB%9A%E5%8A%A8%22%5D%20--%3E%20REP%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Nested CPCV 把网格与特征选择关在每条外层训练块的内层，外层组合测试块不参与选择。</li><li>非嵌套地用 CPCV 路径中位或 PBO 选 \\(\\lambda\\)，是组合版本的 <code>best_score_</code> 偏差。</li><li>报告外层路径分布；PBO 针对已闭合候选，选择程序本身用路径分布评估。</li><li>与 DSR、因果滚动、成本容量串联；交错路径不估冲击。</li><li>出处：Varma and Simon, 2006；Cawley and Talbot, <em>JMLR</em>, 2010；López de Prado, <em>AFML</em>, 第 7、12 章；Bailey, Borwein, López de Prado and Zhu, <em>Journal of Computational Finance</em>, 2017。</li></ul>',2))])}const u=d(p,[["render",B]]);export{b as __pageData,u as default};
